export const initialRealImageList: ImageDataItem[] = rawImageLines.map((line, idx) => {
  const parts = line.split(',');
  const productName = parts[0] || 'Shirt Product';
  const ean = parts[1] || '';
  const toonLabel = parts[2] || '';
  const brand = parts[3] || 'Spark';
  const size = parts[4] || 'M';
  const color = parts[5] || 'Blue';
  return {
    id: `img-real-${idx + 1}`,
    productName,
    ean,
    toonLabel,
    brand,
    size,
    color,
    imageCount: 4,
    sharedToPhoto: idx < 6, // first few pre-delegated for demo
    sharedToCreative: idx < 4,
    photoSharedAt: idx < 6 ? '2026-09-08 14:00' : undefined,
    creativeSharedAt: idx < 4 ? '2026-09-08 14:30' : undefined,
  };
});

// Real EAN list derived from the images & category list
export const initialRealEanList: EANUploadItem[] = initialRealImageList.map((img, idx) => ({
  id: `ean-real-${idx + 1}`,
  productName: img.productName,
  eanCode: img.ean,
  toonLabel: img.toonLabel,
  brand: img.brand,
  size: img.size,
  color: img.color,
  createdAt: '2026-09-08 09:30',
  status: 'Verified',
}));

