export const initialRealInventoryList: ProductInventoryItem[] = rawProductLines.map((line, idx) => {
  const parts = line.split(',');
  const ean = parts[0]?.trim() || '';
  const productName = parts[1]?.trim() || '';
  const brand = parts[2]?.trim() || '';
  const colour = parts[3]?.trim() || '';
  const size = parts[4]?.trim() || '';
  const toonLabel = parts[5]?.trim() || '';
  const sellingPrice = Number(parts[6]) || 690;
  const totalAggregatedStock = Number(parts[7]) || 15;
  const storesCount = Number(parts[8]) || 5;
  const gmFashionsWarehouseStock = Number(parts[9]) || 0;
  const karurStock = Number(parts[10]) || 0;
  const koottappalliStock = Number(parts[11]) || 0;
  const kumbakonamStock = Number(parts[12]) || 0;
  const mallurStock = Number(parts[13]) || 0;
  const namakkalStock = Number(parts[14]) || 0;
  const salemStock = Number(parts[15]) || 0;
  const scraGodownStock = Number(parts[16]) || 0;
  const tiruvannamalaiStock = Number(parts[17]) || 0;
  const wholesaleShowroomStock = Number(parts[18]) || 0;
  const storeBreakdown = parts[19]?.trim() || '';

  return {
    id: `inv-real-${idx + 1}`,
    ean,
    productName,
    brand,
    colour,
    size,
    toonLabel,
    sellingPrice,
    totalAggregatedStock,
    storesCount,
    gmFashionsWarehouseStock,
    karurStock,
    koottappalliStock,
    kumbakonamStock,
    mallurStock,
    namakkalStock,
    salemStock,
    scraGodownStock,
    tiruvannamalaiStock,
    wholesaleShowroomStock,
    storeBreakdown,
    lastUpdated: '2026-09-08 10:00',
  };
});

